      "lineHeight": {
        "pointer": 1.5,
        "touch": 1.5
      },
      "fontWeight": 500,
      "letterSpacing": 0.15
    },
    "headline": {
      "fontSize": {
        "pointer": 24,
        "touch": 24
      },
      "lineHeight": {
        "pointer": 1.3333333333333333,
        "touch": 1.3333333333333333
      },
      "fontWeight": 400,
      "letterSpacing": 0
    },
    "display": {
      "fontSize": {
        "pointer": 36,
        "touch": 36
      },
      "lineHeight": {
        "pointer": 1.2222222222222223,
        "touch": 1.2222222222222223
      },
      "fontWeight": 400,
      "letterSpacing": 0
    }
  },
  "dimension": {
    "shape": {
      "control": "{radius-control}",
      "field": "{radius-field}",
      "chip": "{radius-chip}",
      "card": "{radius-card}",
      "overlay": "{radius-overlay}",
      "dialog": "{radius-dialog}",
      "sheet": "{radius-sheet}",
      "inset": "{radius}"
    },
    "size": {
      "hit": {
        "pointer": 44,
        "touch": 48
      },
      "density": {
        "pointer": {
          "row": 48,
          "pad": 16,
          "gap": 12,
          "surface": 12
        },
        "touch": {
          "row": 56,
          "pad": 16,
          "gap": 12,
          "surface": 16
        }
      },
      "control": {
        "pointer": {
          "row": 48,
          "padding": 8,
          "gap": 12,
          "control": 18,
          "corner": 2,
          "check": 18,
          "dot": 10,
          "tabs": 48,
          "line": 48,
          "clear": 20,
          "switch": "regular"
        },
        "touch": {
          "row": 56,
          "padding": 10,
          "gap": 12,
          "control": 18,
          "corner": 2,
          "check": 18,
          "dot": 10,
          "tabs": 48,
          "line": 56,
          "clear": 24,
          "switch": "regular"
        }
      },
      "height": {
        "pointer": {
          "sm": 32,
          "md": 40,
          "lg": 56
        },
        "touch": {
          "sm": 32,
          "md": 40,
          "lg": 56
        }
      }
    },
    "stroke": {
      "hairline": 1,
      "surface": 0,
      "control": 1,
      "indicator": 3
    },
    "focus": {
      "style": "outline",
      "width": 3,
      "offset": 2
    },
    "icon": {
      "pointer": {
        "sm": 18,
        "md": 20,
        "lg": 24
      },
      "touch": {
        "sm": 18,
        "md": 20,
        "lg": 24
      }
    }
  },
  "shape": {
    "curve": "circular",
    "corners": {
      "field": "top"
    }
  },
  "state": {
    "press-scale": 1,
    "overlay": {
      "hover": 0.08,
      "focus": 0.1,
      "pressed": 0.1,
      "dragged": 0.16
    },
    "ripple": true,
    "pressed-opacity": 1,
    "disabled": {
      "content": 0.38,
      "container": 0.1
    }
  },
  "duration": {
    "shake": 500
  },
  "transition": {
    "enter": {
      "duration": 500,
      "timingFunction": "emphasized-decelerate"
    }
  },
  "motion": {
    "press": {
      "stiffness": 800,
      "damping": 33.94
    },
    "settle": {
      "stiffness": 380,
      "damping": 31.19
    },
    "control": {
      "stiffness": 1600,
      "damping": 80
    },
    "move": {
      "stiffness": 380,
      "damping": 31.19
    }
  },
  "indicator": {
    "tabs": "underline",
    "nav": "fill",
    "field": "underline"
  },
  "finishes": {
    "shared": {
      "card": {
        "gradient": "linear-gradient(180deg, {card} 0%, {card} 100%)",
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)"
      },
      "inset": {
        "material": null,
        "shadow": "none"
      },
      "field": {
        "shadow": "none",
        "material": null
      },
      "raised": {
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {raised} 0%, {raised} 100%)",
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "border-color": "transparent"
      },
      "hover": {
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {hover} 0%, {hover} 100%)",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "border-color": "transparent"
      },
      "pressed": {
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {raised} 0%, {raised} 100%)",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "border-color": "transparent"
      },
      "light": {
        "background": "{primary}",
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "border-color": "transparent",
        "material": null,
        "shadow": "none"
      },
      "accent": {
        "background": "{primary}",
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "border-color": "transparent",
        "material": null,
        "shadow": "none"
      },
      "track": {
        "material": null,
        "shadow": "none",
        "border-color": "{input}"
      },
      "fill": {
        "background": "transparent",
        "shadow": "none",
        "material": null,
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "border-color": "transparent"
      },
      "knob": {
        "material": null,
        "background": "{knob}",
        "gradient": "linear-gradient(180deg, {knob} 0%, {knob} 100%)",
        "shadow": "none",
        "border-color": "transparent"
      },
      "knobOn": {
        "background": "{on-brand}",
        "gradient": "linear-gradient(180deg, {on-brand} 0%, {on-brand} 100%)",
        "shadow": "none",
        "material": null,
        "border-color": "transparent"
      },
      "handle": {
        "material": null,
        "background": "{primary}",
        "gradient": "linear-gradient(180deg, {primary} 0%, {primary} 100%)",
        "shadow": "none",
        "border-color": "transparent"
      },
      "pill": {
        "background": "{raised}",
        "gradient": "linear-gradient(180deg, {raised} 0%, {raised} 100%)",
        "material": {
          "android": {
            "elevation": 1
          }
        },
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 1px 3px 1px oklch(0 0 0 / 0.15)",
        "border-color": "transparent"
      },
      "thumb": {
        "material": null,
        "background": "{secondary}",
        "gradient": "linear-gradient(180deg, {secondary} 0%, {secondary} 100%)",
        "shadow": "none",
        "border-color": "transparent"
      },
      "on": {
        "material": null,
        "background": "{secondary}",
        "gradient": "linear-gradient(180deg, {secondary} 0%, {secondary} 100%)",
        "shadow": "none",
        "border-color": "transparent"
      },
      "chip": {
        "background": "{background}",
        "gradient": "linear-gradient(180deg, {background} 0%, {background} 100%)",
        "border-color": "{border}",
        "material": null,
        "shadow": "none"
      },
      "glass": {
        "border-color": "transparent",
        "backdropFilter": "none",
        "material": {
          "android": {
            "elevation": 3
          }
        },
        "background": "{popover}",
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)"
      },
      "menu": {
        "background": "{popover}",
        "border-color": "transparent",
        "material": {
          "android": {
            "elevation": 3
          }
        },
        "shadow": "0 1px 2px oklch(0 0 0 / 0.3), 0 2px 6px 2px oklch(0 0 0 / 0.15)"
      },
      "dialog": {
        "background": "{popover}",
        "border-color": "transparent",
        "material": {
          "android": {
            "elevation": 6
          }
        },
        "shadow": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)"
      },
      "tooltip": {
        "background": "{inverse}",
        "shadow": "none",
        "border-color": "transparent",
        "material": null
      },
      "inverse": {
        "background": "{inverse}",
        "border-color": "transparent",
        "material": {
          "android": {
            "elevation": 6
          }
        },
        "shadow": "0 1px 3px oklch(0 0 0 / 0.3), 0 4px 8px 3px oklch(0 0 0 / 0.15)"
      },
      "groove": {
        "material": null,
        "shadow": "none"
      }
    },
    "light": {},
    "dark": {}
  }
}

{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "Material (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [0.333333, 1, 0.666667, 1],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [0.333333, 0, 0.666667, 0],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [0.65, 0, 0.35, 1],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [0.2, 0, 0, 1],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [0.05, 0.7, 0.1, 1],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [0.3, 0, 0.8, 0.15],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [0, 0, 0, 1],
      "$description": "WinUI 3 / Fluent 2 Direct Entrance decelerate curve."
    },
    "accelerate": {
      "$value": [1, 0, 1, 1],
      "$description": "WinUI 3 / Fluent 2 Gentle Exit accelerate curve."
    },
    "easy-ease": {
      "$value": [0.33, 0, 0.67, 1],
      "$description": "Fluent Web curveEasyEase."
    },
    "point-to-point": {
      "$value": [0.55, 0.55, 0, 1],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Material 3 Expressive typography scale (TypeScaleTokens.kt / _md-sys-typescale.scss).",
    "$extensions": {
      "dev.aning.shadcn-nsh": {
        "fontFamily": null
      }
    },
    "caption": {
      "$value": {
        "fontFamily": ["system-ui", "sans-serif"],
        "fontSize": "{font.size.caption}",
        "fontWeight": 500,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0.5,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": ["system-ui", "sans-serif"],
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0.4,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": ["system-ui", "sans-serif"],
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
